components.css:
.ds-navigation{display:flex;align-items:center;justify-content:space-between;gap:8px;font-family:var(--font-body)}.ds-nav-current,.ds-nav-item,.ds-settings{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:56px;min-height:42px;padding:7px 13px;border:0;border-radius:var(--radius-control);background:transparent;color:var(--body-ink);font:inherit;line-height:1.5;white-space:nowrap;text-decoration:none;cursor:pointer}.ds-nav-current,.ds-settings{color:var(--gold)}.ds-nav-label::after{content:"";position:absolute;left:0;bottom:-7px;width:72px;height:2px;background:var(--gold);transform:scaleX(0);transform-origin:left center;transition:transform .26s cubic-bezier(.16,1,.3,1);pointer-events:none}.ds-navigation>*:hover,.ds-navigation>*:focus-visible{color:var(--gold)}.ds-navigation>*:hover .ds-nav-label::after,.ds-navigation>*:focus-visible .ds-nav-label::after{transform:scaleX(1)}.ds-navigation>*:focus-visible{outline:2px solid var(--gold);outline-offset:4px}@media(max-width:820px){.ds-navigation{justify-content:flex-start;flex-wrap:wrap;gap:4px 9px}}@media(max-width:620px){.ds-navigation{gap:3px 5px}.ds-navigation>*{padding:6px 10px;font-size:.875rem}}@media(prefers-reduced-motion:reduce){.ds-nav-label::after{transition:none}}.ds-nav-label{position:relative;display:inline-block}@media(max-width:1100px){.ds-navigation{padding-inline-end:16px}}    .ds-home-menu { position: relative; flex: none; }
    .ds-home-trigger { cursor: pointer; }
    .ds-home-menu.is-open .ds-nav-label::after { transform: scaleX(1); }
    .ds-home-submenu { position: absolute; z-index: 10; top: 100%; left: 0; width: 156px; padding-top: 10px; }
    .ds-home-dropdown { display: grid; gap: 0; padding: 0; overflow: hidden; border-radius: var(--radius-control); background: rgb(248 245 237 / .98); box-shadow: var(--shadow-card); }
    .ds-home-dropdown a { display: flex; align-items: center; min-height: 48px; padding: 12px 18px; border-radius: 0; color: var(--body-ink); font-size: var(--type-label); line-height: 1.5; text-decoration: none; }
    .ds-home-dropdown a:hover, .ds-home-dropdown a:focus-visible { background: rgb(134 107 53 / .16); color: var(--gold); }
    .ds-home-dropdown a:focus-visible { outline-offset: -2px; }
@media(max-width:620px){.ds-navigation>.ds-home-menu{padding:0}.ds-home-trigger{padding:6px 10px;font-size:.875rem}}

.ds-news-card{position:relative;overflow:hidden}    .ds-news-actions { position: absolute; z-index: 2; inset-block: 0; right: 0; width: min(46%, 224px); display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); opacity: 0; transform: translateX(100%); pointer-events: none; transition: transform .18s cubic-bezier(.16, 1, .3, 1), opacity .18s ease-out; }
    .ds-news-card:hover .ds-news-actions, .ds-news-card:focus-within .ds-news-actions { opacity: 1; transform: translateX(0); pointer-events: auto; transition-duration: .3s; }
    .ds-news-action { display: flex; align-items: center; justify-content: center; min-width: 0; min-height: 44px; padding: 12px 8px; border: 0; border-radius: 0; background: rgb(248 245 237 / .88); color: var(--gold); font-size: 1.25rem; font-weight: 700; line-height: 1.5; text-decoration: none; cursor: pointer; }
    .ds-news-action:hover { background: rgb(248 245 237 / .97); }
    .ds-news-action:focus-visible { outline-offset: -6px; }
    .ds-news-delete { background: rgb(250 242 240 / .88); color: #a13c30; }
    .ds-news-delete:hover { background: rgb(250 242 240 / .97); }
    .ds-news-action:disabled { opacity: .6; cursor: wait; }
    @media (hover: none), (pointer: coarse) { .ds-news-card { flex-wrap: wrap; } .ds-news-actions { position: static; flex: 0 0 100%; width: 100%; min-height: 48px; border-radius: var(--radius-control); overflow: hidden; opacity: 1; transform: none; pointer-events: auto; transition: none; } .ds-news-action { font-size: 1rem; padding: 10px 8px; } }

.ds-home-menu { position: relative; flex: none; }
.ds-home-trigger { cursor: pointer; }
.ds-home-menu.is-open .ds-nav-label::after { transform: scaleX(1); }
.ds-home-submenu { position: absolute; z-index: 10; top: 100%; left: 0; width: 156px; padding-top: 10px; }
.ds-home-dropdown { display: grid; gap: 0; padding: 0; overflow: hidden; border-radius: var(--radius-control); background: rgb(248 245 237 / .98); box-shadow: var(--shadow-card); }
.ds-home-dropdown a { display: flex; align-items: center; min-height: 48px; padding: 12px 18px; border-radius: 0; color: var(--body-ink); font-size: var(--type-label); line-height: 1.5; text-decoration: none; }
.ds-home-dropdown a:hover, .ds-home-dropdown a:focus-visible { background: rgb(134 107 53 / .16); color: var(--gold); }
.ds-home-dropdown a:focus-visible { outline-offset: -2px; }
